describe('Share Filtered Search URL', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should generate and copy a shareable URL with applied filters', () => {
    // Apply search filters
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="category-electronics"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-0-100"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results-list"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Click the share button
    cy.get('[data-testid="share-button"]').click();

    // Verify share modal appears
    cy.get('[data-testid="share-modal"]').should('be.visible');
    cy.get('[data-testid="share-url-input"]').should('contain', 'laptop&category=electronics&price_range=0-100');

    // Copy the URL to clipboard
    cy.get('[data-testid="copy-to-clipboard-button"]').click();

    // Verify success message
    cy.get('[data-testid="copy-success-message"]').should('be.visible');
    cy.get('[data-testid="copy-success-message"]').should('contain', 'Copied to clipboard');

    // Verify modal closes
    cy.get('[data-testid="share-modal"]').should('not.exist');
  });

  it('should handle multiple filters and edge case of no results', () => {
    // Apply multiple filters
    cy.get('[data-testid="search-input"]').type('monitor');
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="category-electronics"]').click();
    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="brand-dell"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-500-1000"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results-list"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Apply a filter that yields no results
    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="brand-hp"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-10000-20000"]').click();

    // Verify no results message appears
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

    // Click share button to share the empty search state
    cy.get('[data-testid="share-button"]').click();

    // Verify share modal appears with empty state URL
    cy.get('[data-testid="share-modal"]').should('be.visible');
    cy.get('[data-testid="share-url-input"]').should('contain', 'monitor&category=electronics&brand=dell&price_range=10000-20000');

    // Copy the URL to clipboard
    cy.get('[data-testid="copy-to-clipboard-button"]').click();

    // Verify success message
    cy.get('[data-testid="copy-success-message"]').should('be.visible');
    cy.get('[data-testid="copy-success-message"]').should('contain', 'Copied to clipboard');

    // Verify modal closes
    cy.get('[data-testid="share-modal"]').should('not.exist');
  });
});
